import { diagnostics } from "./data.js";

const esc = (value) => String(value).replace(/[&<>\"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;" }[char]));
const badge = (text) => `<span class="badge badge-${text.replaceAll(" ", "-")}">${text}</span>`;
const cover = (kind) => `<span class="cover ${kind}"><i></i><i></i><i></i><i></i></span>`;

export function renderApp(state) {
  if (state.page === "onboarding") state.page = "dashboard";
  const content = renderPage(state);
  return `${renderStudioShell(state, content)}${renderToast(state)}${renderModal(state)}`;
}

function renderStudioShell(state, content) { return `<div class="app-shell studio-shell"><aside class="nav-placeholder" aria-hidden="true"></aside><main class="main">${content}</main></div>`; }
function renderPage(state) {
  let content;
  if (state.page === "dashboard") content = renderWriterLikeDashboard(state);
  else if (state.page === "llm") content = renderLlm(state);
  else if (state.page === "task") content = renderTask(state);
  else if (state.page === "library") content = renderLibrary(state);
  else if (state.page === "history") content = renderHistory(state);
  else if (state.page === "diagnostics") content = renderDiagnostics();
  else if (state.page === "settings") content = renderSettings(state);
  else content = renderRecovery(state);
  if (state.page === "task") return content.replace('<div class="task-title">', '<div class="task-title"><button class="page-back" data-action="route-back" aria-label="返回">‹</button>');
  if (!["dashboard", "llm"].includes(state.page)) return content.replace('<div class="page-heading">', '<div class="page-heading"><button class="page-back" data-action="route-back" aria-label="返回">‹</button>');
  return content;
}

function renderWriterLikeDashboard(state) { return state.conversationMode ? renderLlm(state) : renderComposeDashboard(state); }
function renderComposeDashboard(state) {
  const suggestions = ["把这批文件转成 FLAC", "识别这个文件夹里的音乐格式", "检查 QQ 音乐解密环境", "保留原始文件并输出到新目录"];
  const activeTask = state.processing ? `<button class="active-task-card" data-action="resume-conversation"><span class="active-progress"><b>${state.progress}%</b></span><span class="active-task-copy"><small>进行中的任务</small><strong>正在处理音乐文件</strong><em>TriMusicAgent 正在执行工具调用</em></span><span class="active-task-arrow">继续</span></button>` : "";
  return `<section class="page writer-dashboard compose-mode"><div class="writer-top"><div class="writer-title"><h2>TriMusicAgent</h2><p><span class="subtitle-typewriter"></span></p></div><div class="writer-account"><button class="btn" data-action="toast" data-message="暂无新消息">消息</button><button class="btn account-button" data-page="settings">标准模式</button></div></div><div class="writer-columns"><main><article class="prompt-card"><div class="prompt-editor"><textarea class="form-control" data-input="prompt" maxlength="500" placeholder="告诉 TriMusicAgent 你想怎么处理音乐，例如：扫描 QQ 音乐文件并转成 MP3">${esc(state.promptText)}</textarea><div class="prompt-footer"><span>${state.promptText.length} / 500</span><button class="btn primary" data-action="start">发送</button></div></div></article>${activeTask}<div class="suggestion-row">${suggestions.map((item) => `<button class="btn" data-action="use-suggestion" data-suggestion="${item}">${item}</button>`).join("")}<button class="btn suggestion-refresh" data-action="toast" data-message="已刷新建议">刷新建议</button></div><div class="writer-stats"><article class="writer-stat"><span>处理情况</span><strong>${state.queue.length}</strong><small>待处理文件</small><div class="stat-meta"><b>18</b><small>本周已完成</small></div></article><article class="writer-stat"><span>本地任务</span><strong>24</strong><small>累计 TriMusicAgent 任务</small><div class="stat-meta"><b>92%</b><small>成功完成率</small></div></article><article class="writer-stat"><span>最近使用</span><strong>00:06</strong><small>平均处理时间</small><div class="stat-meta"><b>${state.mode}</b><small>当前权限模式</small></div></article></div><div class="tool-section"><div class="section-head"><h3>常用入口</h3><button class="btn plain-action" data-page="history">查看任务历史</button></div><div class="tool-grid"><button class="btn tool-card" data-page="task"><span class="tool-index">01</span><b>批量处理</b><small>查看 TriMusicAgent 执行过程</small><i>打开</i></button><button class="btn tool-card" data-page="library"><span class="tool-index">02</span><b>音乐库</b><small>浏览已识别的音乐结果</small><i>打开</i></button><button class="btn tool-card" data-page="diagnostics"><span class="tool-index">03</span><b>运行诊断</b><small>确认运行环境是否正常</small><i>检查</i></button><button class="btn tool-card" data-page="llm"><span class="tool-index">04</span><b>模型服务</b><small>配置模型对话服务</small><i>配置</i></button></div></div></main><aside class="writer-aside"><article class="aside-card aside-welcome"><h3>你的音乐，留在你的电脑里</h3><p>文件、会话和任务状态都保存在你选择的工作数据根目录。</p><ul><li>不上传本地音频</li><li>敏感操作先征得同意</li><li>错误会给出下一步建议</li></ul><button class="btn aside-primary" data-action="open-data-settings">查看工作目录</button></article><article class="aside-card aside-recent"><div class="section-head"><h3>最近任务</h3><button class="btn plain-action" data-page="history">全部</button></div>${state.history.slice(0, 3).map((item) => `<button class="btn aside-task" data-page="history"><span class="task-mark">${item.status === "成功" ? "OK" : "error"}</span><span><b>${item.title}</b><small>${item.date}</small></span></button>`).join("")}</article></aside></div></section>`;
}

function renderTask(state) { const steps = ["格式识别", "调用解密器", "运行 FFmpeg", "校验输出文件", "写入元数据", "生成结果"].map((step, index) => `<div class="step ${index < state.stepIndex ? "done" : index === state.stepIndex ? "current" : ""}"><span>${index < state.stepIndex ? "✓" : index + 1}</span><b>${step}</b><small>${index < state.stepIndex ? "已完成" : index === state.stepIndex ? "进行中" : "等待"}</small></div>`).join(""); return `<section class="page task-page"><div class="task-title"><div><h2>周杰伦音乐批量处理</h2><p>5 个文件 · 当前步骤 ${state.stepIndex + 1} / 6 · 模拟任务</p></div><div class="task-actions"><button class="secondary" data-action="approval">请求审批</button><button class="danger-outline" data-action="stop">停止任务</button></div></div><div class="task-grid"><aside class="file-panel"><div class="panel-heading"><b>文件列表</b><span>${state.queue.length}</span></div>${state.queue.map((file) => `<button class="task-file ${file.status === "处理中" ? "selected" : ""}">${cover(file.cover)}<span><b>${file.title}</b><small>${file.platform} · ${file.size}</small></span>${statusDot(file.status)}</button>`).join("")}<button class="add-small" data-action="add-file">添加文件</button></aside><div class="progress-panel"><div class="progress-orb"><span>${state.progress}%</span><small>${state.processing ? "正在处理" : state.taskStatus}</small></div><h3>${state.processing ? "正在识别音乐格式" : "任务已暂停"}</h3><p>TriMusicAgent 正在根据文件来源选择合适的工具链。</p><div class="progress-bar"><i style="width:${state.progress}%"></i></div><div class="steps">${steps}</div><div class="task-bottom"><button class="secondary" data-action="retry">重试失败项</button><button class="primary" data-action="start">${state.processing ? "处理中" : "继续处理"}</button></div></div><aside class="agent-panel"><div class="agent-head"><span class="agent-avatar">TM</span><div><b>TriMusicAgent</b><small>音乐处理助手 · ${state.mode}模式</small></div></div><div class="event-list"><div class="event-heading"><b>操作记录</b><button data-action="collapse-all">全部折叠</button></div>${["格式识别", "调用解密器", "运行 FFmpeg", "读取日志", "错误补救"].map((event, index) => `<div class="event"><button class="event-toggle" data-action="toggle-event"><span>${index < 2 ? "完成" : "待办"}</span>${event}<small>${index < 2 ? "已完成" : "等待"}</small></button><div class="event-body ${index > 1 ? "is-hidden" : ""}">已读取模拟结果，未执行真实工具。</div></div>`).join("")}</div></aside></div></section>`; }
function renderLibrary(state) { const query = state.libraryQuery.toLowerCase(); const rows = state.queue.filter((file) => (!query || `${file.title}${file.artist}`.toLowerCase().includes(query)) && (state.libraryPlatform === "全部" || file.platform === state.libraryPlatform) && (state.libraryFormat === "全部" || file.input === state.libraryFormat)).map((file) => `<tr><td>${cover(file.cover)}<span class="file-name"><b>${file.title}</b><small>${file.artist}</small></span></td><td>${badge(file.platform)}</td><td><code>${file.input}</code></td><td><code>${file.output}</code></td><td>${badge(file.status)}</td><td>${file.size}</td><td><button class="link-button" data-action="toast" data-message="已打开文件操作菜单">•••</button></td></tr>`).join(""); return `<section class="page"><div class="page-heading"><div><h2>音乐库</h2><p>查看已识别的音乐文件与处理结果。</p></div><button class="primary" data-action="add-file">＋ 添加音乐</button></div><div class="filter-bar"><input data-input="library-query" value="${esc(state.libraryQuery)}" placeholder="搜索文件名、艺术家或路径" /><select data-input="library-platform"><option>全部</option><option>QQ 音乐</option><option>网易云音乐</option><option>本地文件</option></select><select data-input="library-format"><option>全部</option><option>ncm</option><option>mgg</option><option>qmc3</option><option>kgm</option></select></div><div class="library-card"><table><thead><tr><th>音乐文件</th><th>平台</th><th>输入格式</th><th>输出格式</th><th>状态</th><th>大小</th><th>操作</th></tr></thead><tbody>${rows || `<tr><td colspan="7" class="empty">没有匹配的音乐文件</td></tr>`}</tbody></table></div></section>`; }
function renderHistory(state) { return `<section class="page"><div class="page-heading"><div><h2>任务历史</h2><p>每个 TriMusicAgent 任务都可以恢复、重试和查看诊断信息。</p></div><button class="secondary" data-action="toast" data-message="已导出任务摘要">导出任务摘要</button></div><div class="history-tabs"><button class="active">全部</button><button>成功</button><button>失败</button><button>处理中</button><button>已停止</button><input placeholder="搜索任务名称" /></div><div class="history-list">${state.history.map((item) => `<article class="history-row"><div class="history-main"><b>${item.title}</b><small>${item.date} · ${item.total} 个文件 · 总耗时 ${item.time}</small></div><div class="history-numbers"><span class="good">${item.success} 成功</span><span class="bad">${item.failed} 失败</span></div>${badge(item.status)}<div class="row-actions"><button data-action="toast" data-message="已打开任务详情">查看</button><button data-action="retry">重试</button><button data-action="toast" data-message="已打开输出目录">打开目录</button></div></article>`).join("")}</div></section>`; }
function renderDiagnostics() { return `<section class="page"><div class="page-heading"><div><h2>诊断中心</h2><p>运行前先确认外部依赖与本地数据边界。</p></div><button class="primary" data-action="diagnose">运行完整诊断</button></div><div class="health-banner"><div><span class="health-icon">✓</span><b>系统基本正常</b><small>7 项正常 · 1 项提示</small></div><div><span class="health-icon warn">!</span><b>网易云音乐未运行</b><small>文件级处理不要求客户端进程</small></div></div><div class="diagnostic-card"><table><thead><tr><th>检查项目</th><th>状态</th><th>检测结果</th><th>最后检测时间</th><th>操作</th></tr></thead><tbody>${diagnostics.map(([name, status, result, time]) => `<tr><td><b>${name}</b></td><td>${status === "正常" ? "● 正常" : "● 提示"}</td><td><code>${result}</code></td><td>${time}</td><td><button class="link-button" data-action="toast" data-message="已重新检测 ${name}">重新检测</button></td></tr>`).join("")}</tbody></table></div><div class="diagnostic-footer"><button class="secondary" data-action="toast" data-message="诊断报告已准备好">导出诊断报告</button><button class="secondary" data-action="toast" data-message="错误摘要已复制">复制错误摘要</button></div></section>`; }
function renderSettings(state) { const tabs = [["model", "模型设置"], ["permission", "权限设置"], ["limits", "任务限制"], ["tools", "工具管理"], ["data", "数据与会话"]]; return `<section class="page settings-page"><div class="page-heading"><div><h2>设置</h2><p>配置模型、权限、工具和会话边界。</p></div><button class="primary" data-action="save-settings">保存设置</button></div><div class="settings-layout"><aside class="settings-tabs">${tabs.map(([id, label]) => `<button class="${state.settingsTab === id ? "active" : ""}" data-settings-tab="${id}">${label}<span>›</span></button>`).join("")}</aside><div class="settings-content">${renderSettingsTab(state)}</div></div></section>`; }
function renderSettingsTab(state) { if (state.settingsTab === "permission") return `<div class="setting-block"><h3>权限模式</h3><p>应用可以管理员启动，但 TriMusicAgent 的操作仍由权限模式控制。</p><div class="mode-cards">${["受限", "标准", "完全访问"].map((mode) => `<button class="mode-card ${state.mode === mode ? "selected" : ""}" data-mode="${mode}"><b>${mode}</b><small>${mode === "受限" ? "只检测和提示敏感操作" : mode === "标准" ? "敏感操作需要你的审批" : "允许范围内自动执行"}</small></button>`).join("")}</div><label class="setting-switch"><span>联网访问</span><input type="checkbox" checked /><i></i></label><label class="setting-switch"><span>默认管理员启动</span><input type="checkbox" checked /><i></i></label></div>`; if (state.settingsTab === "limits") return `<div class="setting-block"><h3>任务限制</h3><div class="field-grid"><label>单步骤最大重试次数<input value="2" /></label><label>单任务最大模型轮数<input value="8" /></label><label>单任务最大工具调用数<input value="16" /></label><label>单任务总超时<input value="15 分钟" /></label></div><div class="notice amber">超过限制后立即停止任务，避免无限重试和继续消耗 Token。</div></div>`; if (state.settingsTab === "tools") return `<div class="setting-block"><h3>工具管理</h3><p>只有协议版本兼容、Schema 校验通过的工具才允许热插拔。</p><div class="tool-table">${[["音乐格式识别", "v1.0.0"], ["QQ 音乐解密器", "v2.1"], ["网易云 NCM", "v1.4.2"], ["FFmpeg", "7.0.2"]].map(([name, version]) => `<div><b>${name}</b><code>${version}</code><span>已启用</span><button data-action="toast" data-message="已刷新协议">检查协议</button></div>`).join("")}</div></div>`; if (state.settingsTab === "data") return `<div class="setting-block"><h3>数据与会话</h3><label>工作数据根目录<input value="${esc(state.workspaceRoot)}" readonly /></label><div class="path-preview">session/2026/08/22/&lt;session-id&gt;/</div><label class="setting-switch"><span>保留原始会话</span><input type="checkbox" checked /><i></i></label><label class="setting-switch"><span>接近上下文边界时提醒压缩</span><input type="checkbox" checked /><i></i></label><button class="secondary" data-page="recovery">打开会话压缩</button></div>`; return `<div class="setting-block"><h3>模型设置</h3><div class="field-grid"><label>模型提供商<select data-input="model-provider"><option>OpenAI-compatible</option><option>自定义接口</option></select></label><label>模型名称<input data-input="model-name" value="${state.modelConfig?.model || "DeepSeek-R1"}" /></label><label>API Base URL<input data-input="model-base-url" value="${state.modelConfig?.baseUrl || "https://api.example.com/v1"}" /></label><label>请求超时（秒）<input data-input="model-timeout" type="number" value="${Math.round((state.modelConfig?.connectTimeoutMs || 60000) / 1000)}" /></label></div><button class="secondary" data-action="test-llm">测试连接</button></div>`; }
function renderRecovery(state) { return `<section class="page recovery-page"><div class="page-heading"><div><h2>错误恢复与会话压缩</h2><p>处理失败时先止损，再决定重试、换工具或压缩上下文。</p></div></div><div class="recovery-grid"><article class="error-card"><div class="card-heading"><h3>解密器读取失败</h3><span class="status-icon bad">!</span></div><p>QQ 音乐进程未运行，当前权限模式不允许自动启动。</p><div class="button-row"><button class="primary" data-action="approval">请求审批</button><button class="secondary" data-action="retry">重试</button></div></article><article class="compression-card"><div class="card-heading"><h3>会话压缩</h3><span class="compression-ring">72%</span></div><div class="token-stats"><div><b>156</b><small>原始消息数</small></div><div><b>68,432</b><small>当前 Token</small></div><div><b>18,742</b><small>预计压缩后</small></div><div><b>72.6%</b><small>预计节省</small></div></div><label class="setting-switch"><span>生成 Markdown 检查点</span><input type="checkbox" checked /><i></i></label><button class="primary large" data-action="compress">${state.compressionDone ? "压缩已完成" : "开始压缩"}</button></article></div></section>`; }
function renderModal(state) { if (state.modal !== "approval") return ""; return `<div class="modal-backdrop"><section class="approval-modal"><div class="modal-title"><span class="status-icon warn">!</span><h3>需要你的确认</h3><button data-action="close-modal">关闭</button></div><div class="approval-risk">标准模式 · 中风险操作</div><dl><dt>操作名称</dt><dd>启动 QQ 音乐并附加解密器</dd><dt>目标路径</dt><dd><code>C:\\Users\\Public\\QQMusic\\QQMusic.exe</code></dd></dl><div class="button-row"><button class="primary" data-action="allow-once">允许一次</button><button class="secondary" data-action="allow-task">允许本任务</button><button class="danger" data-action="deny">拒绝</button></div></section></div>`; }
function renderToast(state) { return state.toast ? `<div class="toast">✓ ${esc(state.toast)}</div>` : ""; }
function statusDot(status) { return `<span class="status-dot ${status === "已完成" ? "good" : status === "失败" ? "bad" : status === "处理中" ? "working" : "idle"}"></span>`; }

function renderLlm(state) {
  const taskMode = state.conversationMode;
  const messages = taskMode ? state.agentMessages.map((message) => message.role === "user" ? `<div class="llm-chat-message user"><p>${esc(message.text)}</p><span class="llm-avatar user-avatar">你</span></div>` : `<div class="llm-chat-message assistant"><span class="llm-avatar">T</span><div><p>${esc(message.text)}</p></div></div>`).join("") : state.llmMessages.map((message) => message.role === "error" ? `<div class="llm-error-message"><div><strong>AI 连接错误</strong><p>${esc(message.text)}</p></div><button data-action="retry-llm">重试</button></div>` : message.role === "notice" ? `<div class="llm-system-notice"><span>${esc(message.text)}</span></div>` : message.role === "user" ? `<div class="llm-chat-message user"><p>${esc(message.text)}</p><span class="llm-avatar user-avatar">你</span></div>` : `<div class="llm-chat-message assistant"><span class="llm-avatar">T</span><div><p>${esc(message.text)}</p></div></div>`).join("");
  const events = state.toolEvents.map((event, index) => `<div class="tool-event ${event.status}"><span class="tool-event-index">${index + 1}</span><div><b>${event.name}</b><small>${event.detail}</small></div><span class="tool-event-status">${event.status === "done" ? "完成" : event.status === "running" ? "进行中" : "等待"}</span></div>`).join("");
  const execution = taskMode ? `<div class="llm-execution-sticky ${state.executionCollapsed ? "is-collapsed" : ""}"><div class="llm-execution-head"><strong>Agent 执行过程</strong><span>${state.progress}%</span><button data-action="toggle-conversation-log">${state.executionCollapsed ? "展开" : "收起"}</button></div><div class="execution-bar"><i style="width:${state.progress}%"></i></div><div class="llm-execution-events">${events}</div></div>` : "";
  const streaming = state.llmStreaming ? `<div class="llm-chat-message assistant streaming"><span class="llm-avatar">T</span><div><p>${esc(state.llmStreaming.text.slice(0, state.llmStreaming.index))}<span class="streaming-caret">▋</span></p></div></div>` : "";
  const retry = state.llmRetry ? `<div class="llm-retry-status"><span class="retry-spinner"></span>正在重新连接 ${state.llmRetry.attempt}/${state.llmRetry.max}</div>` : "";
  const modeMenu = state.modeMenuOpen ? `<div class="llm-mode-menu">${["受限", "标准", "完全访问"].map((mode) => `<button data-action="select-mode" data-mode="${mode}">${mode}</button>`).join("")}</div>` : "";
  const sendAction = taskMode ? "start" : state.llmStreaming ? "interrupt-llm" : "llm-send";
  return `<section class="page llm-chat-page ${taskMode ? "task-chat-page" : ""}"><header class="llm-chat-header"><button class="llm-back" data-action="route-back">‹</button><span>${taskMode ? "当前任务" : "模型对话"}</span>${taskMode ? `<button class="kimi-action-button" data-action="stop">停止任务</button>` : ""}</header><div class="llm-chat-scroll"><div class="llm-chat-content">${execution}${messages}${retry}${streaming}</div></div><button class="to-bottom-button" data-action="scroll-bottom" aria-label="回到底部">↓</button><div class="llm-composer"><div class="llm-paths"></div><div class="llm-input" contenteditable="true" role="textbox" aria-multiline="true" aria-disabled="false" aria-label="向 TriMusicAgent 发送你的想法" data-input="prompt" data-placeholder="向 TriMusicAgent 发送你的想法">${esc(state.promptText)}</div><div class="llm-composer-footer"><button class="llm-add-path" data-action="add-path" aria-label="添加路径">＋</button><div class="llm-context-controls"><div class="llm-mode-wrap"><button class="llm-context-mode" data-action="cycle-mode">${state.mode}模式⌄</button>${modeMenu}</div><button class="llm-context-network" data-action="toggle-network">${state.networkEnabled ? "联网检索模式" : "离线"}</button></div><span class="context-meter" style="--usage:${state.contextUsage}%"><b>${state.contextUsage}%</b></span><button class="llm-send ${state.llmStreaming ? "is-interrupt" : ""}" data-action="${sendAction}" aria-label="${state.llmStreaming ? "打断" : "发送"}">${state.llmStreaming ? "■" : "↑"}</button></div></div><small class="llm-disclaimer">内容由 AI 生成，请仔细甄别</small></section>`;
}
